CREATE OR REPLACE FUNCTION public.focal_media_scope(_uid uuid,_path text,_write boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN public.focal_beneficiary_scope(_uid,split_part(_path,'/',2)::uuid,_write); EXCEPTION WHEN invalid_text_representation THEN RETURN false; END $$;
REVOKE ALL ON FUNCTION public.focal_media_scope(uuid,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.focal_media_scope(uuid,text,boolean) TO authenticated,service_role;
CREATE POLICY focal_media_read_guard ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING (bucket_id<>'beneficiary-media' OR NOT public.facility_restricted_user(auth.uid()) OR public.focal_media_scope(auth.uid(),name));
CREATE POLICY focal_media_insert_guard ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (bucket_id<>'beneficiary-media' OR NOT public.facility_restricted_user(auth.uid()) OR public.focal_media_scope(auth.uid(),name,true));
CREATE POLICY focal_media_update_guard ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING (bucket_id<>'beneficiary-media' OR NOT public.facility_restricted_user(auth.uid()) OR public.focal_media_scope(auth.uid(),name,true)) WITH CHECK (bucket_id<>'beneficiary-media' OR NOT public.facility_restricted_user(auth.uid()) OR public.focal_media_scope(auth.uid(),name,true));
CREATE POLICY focal_media_delete_guard ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING (bucket_id<>'beneficiary-media' OR NOT public.facility_restricted_user(auth.uid()) OR public.focal_media_scope(auth.uid(),name,true));
CREATE POLICY focal_media_read_grant ON storage.objects FOR SELECT TO authenticated USING (bucket_id='beneficiary-media' AND public.facility_restricted_user(auth.uid()) AND public.focal_media_scope(auth.uid(),name));
CREATE POLICY focal_media_insert_grant ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='beneficiary-media' AND public.facility_restricted_user(auth.uid()) AND public.focal_media_scope(auth.uid(),name,true));
CREATE POLICY focal_referral_insert_grant ON public.beneficiary_referrals FOR INSERT TO authenticated WITH CHECK (created_by=auth.uid() AND public.facility_restricted_user(auth.uid()) AND public.focal_beneficiary_scope(auth.uid(),beneficiary_id,true));
CREATE POLICY focal_audit_insert_grant ON public.beneficiary_audit FOR INSERT TO authenticated WITH CHECK (actor_id=auth.uid() AND public.facility_restricted_user(auth.uid()) AND public.focal_beneficiary_scope(auth.uid(),beneficiary_id,true));